from itsdangerous import Serializer
from typing import Union, List, Optional, Any


def create_serializer(secret_key: Union[str, List[str]], salt: Optional[str] = None) -> Any:
    """Creates a new serializer instance with the given secret key and optional salt. secret_key: The secret key to sign and verify with. Can be a list of keys, oldest to newest, to support key rotation. salt: Extra key to combine with secret_key to distinguish signatures in different contexts. Example: create_serializer('my-secret-key', 'session-context') -> Serializer instance."""
    try:
        return Serializer(secret_key, salt=salt)
    except Exception as e:
        raise ValueError(f"Failed to create serializer: {str(e)}") from e

from itsdangerous import Serializer, BadSignature


def verify_and_deserialize(secret_key: str, signed_string: str, salt: str | None = None) -> dict[str, str | int | float | bool | None] | list | str | int | float | bool:
    """Verifies the signature of a signed string and deserializes the object. secret_key: The secret key used for signing and verification. signed_string: The signed string to verify and deserialize. salt: Salt to use for the signature. Returns the deserialized object."""
    try:
        serializer = Serializer(secret_key, salt=salt.encode() if salt else None)
        result = serializer.loads(signed_string)
        return result
    except BadSignature as e:
        raise ValueError(f"signature verification failed: {str(e)}")
    except Exception as e:
        raise ValueError(f"failed to verify and deserialize: {str(e)}")

from itsdangerous import Serializer


def deserialize_without_verification(secret_key: str, signed_string: str, salt: str | None = None) -> dict[str, bool | str | None]:
    """Deserializes a signed string without verifying the signature. secret_key: The secret key used for signing and verification, signed_string: The signed string to deserialize without verification, salt: Salt to use for the serializer. Returns a dictionary with 'signature_valid' (bool) and 'payload' (str or None)."""
    try:
        serializer = Serializer(secret_key, salt=salt.encode() if salt else None)
        signature_valid, payload = serializer.loads_unsafe(signed_string)
        return {"signature_valid": signature_valid, "payload": str(payload) if payload is not None else None}
    except Exception as e:
        raise ValueError(f"Failed to deserialize string: {str(e)}")

from itsdangerous import TimedSerializer
import json


def create_timed_serializer(secret_key: str, salt: str | None = None, serializer: object | None = None) -> dict[str, str]:
    """Create a timed serializer for signing and verifying data with expiration. secret_key: The secret key used for signing and verifying signatures. salt: A salt value to use for the signer. serializer: The serializer to wrap; defaults to JSONSerializer. Returns a dictionary with the serializer's representation."""
    if serializer is None:
        serializer = json

    try:
        timed_serializer = TimedSerializer(secret_key, salt=salt, serializer=serializer)
        return {
            "repr": str(timed_serializer),
            "secret_key": secret_key,
            "salt": salt or ""
        }
    except Exception as e:
        raise ValueError(f"Failed to create timed serializer: {str(e)}")

from itsdangerous import TimedSerializer, SignatureExpired, BadSignature


def verify_and_deserialize_with_expiry(
    signed_string: str,
    secret_key: str,
    max_age: int | None = None,
    salt: str | None = None,
) -> dict[str, str | int | float | bool | None] | list | str:
    """Verify a signed string with timestamp and deserialize it, checking for expiration. signed_string: The signed string to verify and deserialize. secret_key: The secret key used to sign the string. max_age: Maximum age in seconds for the signature to be valid. salt: Salt to use for the signature verification. Example: verify_and_deserialize_with_expiry('eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...', 'my_secret', max_age=3600) -> {'data': 'example'}."""
    try:
        serializer = TimedSerializer(secret_key, salt=salt)
        result = serializer.loads(signed_string, max_age=max_age, return_timestamp=False)
        return result
    except SignatureExpired as e:
        raise ValueError(f"Signature has expired: {str(e)}")
    except BadSignature as e:
        raise ValueError(f"Invalid signature: {str(e)}")
    except Exception as e:
        raise ValueError(f"Failed to verify and deserialize: {str(e)}")

from itsdangerous import Signer


def sign_data(secret_key: str, value: str) -> str:
    """Signs the given string. secret_key: The secret key used for signing, e.g. 'my_secret_key' -> 'hello.world.signature'. value: The string or bytes value to sign, e.g. 'hello.world'."""
    try:
        signer = Signer(secret_key)
        signature = signer.sign(value)
        return signature.decode('utf-8')
    except Exception as e:
        raise ValueError(f"Failed to sign data: {str(e)}")

from itsdangerous import Signer
from itsdangerous.exc import BadSignature


def verify_signature_only(value: str, signature: str, secret_key: str) -> bool:
    """Verifies the signature for the given value. value: the value to verify the signature for, signature: the signature to verify against the value, secret_key: the secret key used for signing. Example: verify_signature_only('hello', 'sig', 'key') -> True."""
    try:
        signer = Signer(secret_key)
        return signer.verify_signature(value, signature)
    except BadSignature:
        return False
    except Exception as e:
        raise ValueError(f"Failed to verify signature: {str(e)}")

from itsdangerous import TimestampSigner, SignatureExpired


def verify_and_extract_with_timestamp(signed_value: str, secret_key: str, max_age: int | None = None) -> str:
    """Verify a signed value with timestamp and extract the original data. signed_value: the signed value to verify, secret_key: the secret key used for signing, max_age: maximum age in seconds for the signature to be valid. Example: verify_and_extract_with_timestamp('abc123', 'mykey', 3600) -> 'original_data'."""
    try:
        signer = TimestampSigner(secret_key)
        unsigned_data = signer.unsign(signed_value, max_age=max_age, return_timestamp=False)
        return unsigned_data.decode('utf-8')
    except SignatureExpired as e:
        raise ValueError("Signature has expired") from e
    except Exception as e:
        raise ValueError(f"Failed to verify and extract signed value: {str(e)}") from e

import base64
from itsdangerous import base64_encode as itsdangerous_base64_encode


def base64_encode_url_safe(string: str | bytes) -> str:
    """Base64 encode a string of bytes or text. The resulting bytes are safe to use in URLs. string: The string or bytes to encode using URL-safe base64 encoding, e.g. 'hello' -> 'aGVsbG8'."""
    try:
        result = itsdangerous_base64_encode(string)
        return result.decode('ascii')
    except Exception as e:
        raise ValueError(f"Failed to encode: {string!r}") from e
